//! 📦️ Literal OPC entities compose an enclosing owned native stream.
use semio_framework_value::{NativeEncodeControl,NativeDecodeControl,ValueError,ValueRefusalKind};
use super::{OpcPackage,OpcPart,OpcContentTypes,OpcRelationship,OpcTargetMode,OpcRelationshipOwners};
use semio_framework_os_kernel::sqlite_snapshot::{SnapshotEncoding,SqliteDatabaseLimits};
use semio_s_artifact_stdio_xml::schema::snapshot::{XmlDocument,XmlNativeEmission,XmlNativeInput,emit_xml_native_document,read_xml_native_document,sqlite::XmlDocumentView};


/// 🛫️ One cumulative stream for the actual OPC package and its enclosing fields.
pub struct OpcNativeWriter<'a,'p,'o>{pub control:&'a mut NativeEncodeControl<'p>,pub output:Option<&'o mut Vec<u8>>,pub count:usize,pub rows:usize,pub limits:SqliteDatabaseLimits,pub encoding:SnapshotEncoding}
impl OpcNativeWriter<'_, '_, '_>{
 pub fn raw(&mut self,bytes:&[u8])->Result<(),ValueError>{self.count.checked_add(bytes.len()).filter(|size|*size<=self.limits.max_file_bytes&&*size<=self.limits.max_value_bytes).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"OPC native output exceeds caller ceiling"))?;for chunk in bytes.chunks(256){if let Some(output)=&mut self.output{if output.len().checked_add(chunk.len()).filter(|size|*size<=output.capacity()).is_none(){return Err(ValueError::new(ValueRefusalKind::InvariantViolated,"OPC native output exceeds admitted capacity"));}output.extend_from_slice(chunk);}self.count+=chunk.len();self.control.advance(chunk.len())?;}Ok(())}
 pub fn rows(&mut self,count:usize)->Result<(),ValueError>{self.rows=self.rows.checked_add(count).filter(|count|*count<=self.limits.max_rows).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"OPC native entities exceed caller ceiling"))?;Ok(())}
 pub fn delimiter(&mut self,bytes:&[u8])->Result<(),ValueError>{if self.encoding==SnapshotEncoding::Text{self.raw(bytes)?;}Ok(())}
 pub fn unsigned(&mut self,mut value:u64)->Result<(),ValueError>{if self.encoding==SnapshotEncoding::Binary{let mut bytes=[0;10];let mut count=0;loop{bytes[count]=(value&127)as u8;value>>=7;if value!=0{bytes[count]|=128;}count+=1;if value==0{break;}}return self.raw(&bytes[..count]);}let mut bytes=[0;20];let mut start=20;loop{start-=1;bytes[start]=b'0'+(value%10)as u8;value/=10;if value==0{break;}}self.raw(&bytes[start..])}
 pub fn octets(&mut self,bytes:&[u8])->Result<(),ValueError>{if self.encoding==SnapshotEncoding::Binary{self.unsigned(bytes.len()as u64)?;return self.raw(bytes);}const DIGITS:&[u8;16]=b"0123456789abcdef";let mut output=[0;512];for chunk in bytes.chunks(256){for(index,byte)in chunk.iter().enumerate(){output[index*2]=DIGITS[usize::from(byte>>4)];output[index*2+1]=DIGITS[usize::from(byte&15)];}self.raw(&output[..chunk.len()*2])?;}Ok(())}
 pub fn string(&mut self,text:&str)->Result<(),ValueError>{self.octets(text.as_bytes())}
 pub fn list<T>(&mut self,values:&[T],mut emit:impl FnMut(&mut Self,&T)->Result<(),ValueError>)->Result<(),ValueError>{self.rows(values.len())?;self.delimiter(b"[")?;if self.encoding==SnapshotEncoding::Binary{self.unsigned(values.len()as u64)?;}for(index,value)in values.iter().enumerate(){if index!=0{self.delimiter(b",")?;}emit(self,value)?;}self.delimiter(b"]")}
 pub fn list_iter<'value,T:'value>(&mut self,values:impl ExactSizeIterator<Item=&'value T>,mut emit:impl FnMut(&mut Self,&T)->Result<(),ValueError>)->Result<(),ValueError>{let count=values.len();self.rows(count)?;self.delimiter(b"[")?;if self.encoding==SnapshotEncoding::Binary{self.unsigned(count as u64)?;}for(index,value)in values.enumerate(){if index!=0{self.delimiter(b",")?;}emit(self,value)?;}self.delimiter(b"]")}
 pub fn document(&mut self,document:XmlDocumentView<'_>)->Result<(),ValueError>{emit_xml_native_document(document,XmlNativeEmission{control:&mut *self.control,output:self.output.as_deref_mut(),count:&mut self.count,rows:&mut self.rows,limits:self.limits,encoding:self.encoding})}
 pub fn package(&mut self,package:&OpcPackage)->Result<(),ValueError>{
  self.rows(1)?;self.delimiter(b"[")?;self.list(&package.parts,|writer,part|{writer.delimiter(b"[")?;writer.string(&part.path)?;writer.delimiter(b",")?;writer.string(&part.content_type)?;writer.delimiter(b",")?;writer.octets(&part.bytes)?;writer.delimiter(b"]")})?;self.delimiter(b",")?;
  self.list(&package.content_types.defaults,|writer,(key,value)|{writer.delimiter(b"[")?;writer.string(key)?;writer.delimiter(b",")?;writer.string(value)?;writer.delimiter(b"]")})?;self.delimiter(b",")?;
  self.list(&package.content_types.overrides,|writer,(key,value)|{writer.delimiter(b"[")?;writer.string(key)?;writer.delimiter(b",")?;writer.string(value)?;writer.delimiter(b"]")})?;self.delimiter(b",")?;
  self.rows(package.relationships.owner_count())?;self.delimiter(b"[")?;if self.encoding==SnapshotEncoding::Binary{self.unsigned(package.relationships.owner_count()as u64)?;}for(index,(owner,relationships))in package.relationships.groups().enumerate(){if index!=0{self.delimiter(b",")?;}self.delimiter(b"[")?;self.string(owner)?;self.delimiter(b",")?;self.list(relationships,|writer,relationship|{writer.delimiter(b"[")?;writer.string(&relationship.id)?;writer.delimiter(b",")?;writer.string(&relationship.rel_type)?;writer.delimiter(b",")?;writer.string(&relationship.target)?;writer.delimiter(b",")?;writer.unsigned(u64::from(relationship.target_mode==OpcTargetMode::External))?;writer.delimiter(b"]")})?;self.delimiter(b"]")?;}self.delimiter(b"],")?;self.string(&package.comment)?;self.delimiter(b"]")
 }
}

/// 🛬️ An enclosing borrowed cursor with cumulative typed ownership admission.
pub struct OpcNativeReader<'i,'a,'p>{pub bytes:&'i[u8],pub position:usize,pub rows:usize,pub limits:SqliteDatabaseLimits,pub binary:bool,pub control:&'a mut NativeDecodeControl<'p>}
impl OpcNativeReader<'_, '_, '_>{
 pub fn rows(&mut self,count:usize)->Result<(),ValueError>{self.rows=self.rows.checked_add(count).filter(|count|*count<=self.limits.max_rows).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"OPC native entities exceed caller ceiling"))?;Ok(())}
 pub fn take(&mut self,count:usize)->Result<&[u8],ValueError>{let end=self.position.checked_add(count).filter(|end|*end<=self.bytes.len()).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"OPC native input is truncated"))?;let start=self.position;while self.position<end{let next=self.position.saturating_add(256).min(end);self.control.advance(next-self.position)?;self.position=next;}Ok(&self.bytes[start..end])}
 pub fn delimiter(&mut self,byte:u8)->Result<(),ValueError>{if !self.binary&&self.take(1)?[0]!=byte{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"OPC native delimiter differs"));}Ok(())}
 pub fn unsigned(&mut self)->Result<u64,ValueError>{if self.binary{let mut value=0;for shift in(0..70).step_by(7){let byte=self.take(1)?[0];if shift==63&&byte>1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"OPC native integer exceeds unsigned64"));}value|=u64::from(byte&127)<<shift;if byte&128==0{return Ok(value);}}return Err(ValueError::new(ValueRefusalKind::InvalidValue,"OPC native integer is overlong"));}let start=self.position;let mut value=0u64;while self.bytes.get(self.position).is_some_and(u8::is_ascii_digit){let byte=self.take(1)?[0];value=value.checked_mul(10).and_then(|value|value.checked_add(u64::from(byte-b'0'))).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"OPC native integer exceeds unsigned64"))?;}if self.position==start||self.position-start>1&&self.bytes[start]==b'0'{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"OPC native integer is not canonical"));}Ok(value)}
 pub fn octets(&mut self)->Result<Vec<u8>,ValueError>{
  if self.binary{let count=usize::try_from(self.unsigned()?).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"OPC intrinsic length exceeds platform width"))?;let start=self.position;self.take(count)?;return self.control.copy_bytes(&self.bytes[start..self.position]);}
  let start=self.position;while self.bytes.get(self.position).is_some_and(u8::is_ascii_hexdigit){let mut count=0;while count<256&&self.bytes.get(self.position+count).is_some_and(u8::is_ascii_hexdigit){count+=1;}self.take(count)?;}let count=self.position-start;if count%2!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"OPC native octets have odd hexadecimal width"));}let mut output=self.control.allocate_vec::<u8>(count/2)?;self.control.scoped_stage(|control|{control.begin_stage(count/2)?;for chunk in self.bytes[start..self.position].chunks(512){for pair in chunk.chunks_exact(2){output.push((digit(pair[0])?<<4)|digit(pair[1])?);}control.advance(chunk.len()/2)?;}Ok::<(),ValueError>(())})?;Ok(output)
 }
 pub fn string(&mut self)->Result<String,ValueError>{let bytes=self.octets()?;self.control.borrow_text(&bytes)?;String::from_utf8(bytes).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"OPC native text is not UTF-8"))}
 pub fn reserve<T>(&mut self,values:&mut Vec<T>)->Result<(),ValueError>{if values.len()==values.capacity(){self.control.charge(values.len().checked_add(64).and_then(|count|count.checked_mul(std::mem::size_of::<T>())).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"OPC native frontier size overflow"))?)?;values.try_reserve_exact(64).map_err(|_|ValueError::new(ValueRefusalKind::AllocationFailed,"OPC native frontier allocation failed"))?;}Ok(())}
 pub fn list<T>(&mut self,mut parse:impl FnMut(&mut Self)->Result<T,ValueError>)->Result<Vec<T>,ValueError>{self.delimiter(b'[')?;let count=if self.binary{usize::try_from(self.unsigned()?).map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"OPC collection length exceeds platform width"))?}else{0};if self.binary{self.rows(count)?;}let mut values=self.control.allocate_vec(count)?;while if self.binary{values.len()<count}else{self.bytes.get(self.position)!=Some(&b']')}{if !self.binary{self.rows(1)?;self.reserve(&mut values)?;}if !values.is_empty(){self.delimiter(b',')?;}values.push(parse(self)?);}self.delimiter(b']')?;Ok(values)}
 pub fn document(&mut self)->Result<XmlDocument,ValueError>{read_xml_native_document(XmlNativeInput{bytes:self.bytes,position:&mut self.position,rows:&mut self.rows,limits:self.limits,binary:self.binary,control:&mut *self.control})}
 pub fn package(&mut self)->Result<OpcPackage,ValueError>{
  self.rows(1)?;self.delimiter(b'[')?;let parts=self.list(|reader|{reader.delimiter(b'[')?;let path=reader.string()?;reader.delimiter(b',')?;let content_type=reader.string()?;reader.delimiter(b',')?;let bytes=reader.octets()?;reader.delimiter(b']')?;Ok(OpcPart{path,content_type,bytes})})?;self.delimiter(b',')?;
  let defaults=self.list(|reader|{reader.delimiter(b'[')?;let key=reader.string()?;reader.delimiter(b',')?;let value=reader.string()?;reader.delimiter(b']')?;Ok((key,value))})?;self.delimiter(b',')?;
  let overrides=self.list(|reader|{reader.delimiter(b'[')?;let key=reader.string()?;reader.delimiter(b',')?;let value=reader.string()?;reader.delimiter(b']')?;Ok((key,value))})?;self.delimiter(b',')?;
  let owners=self.list(|reader|{reader.delimiter(b'[')?;let owner=reader.string()?;reader.delimiter(b',')?;let relationships=reader.list(|reader|{reader.delimiter(b'[')?;let id=reader.string()?;reader.delimiter(b',')?;let rel_type=reader.string()?;reader.delimiter(b',')?;let target=reader.string()?;reader.delimiter(b',')?;let target_mode=match reader.unsigned()?{0=>OpcTargetMode::Internal,1=>OpcTargetMode::External,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"OPC native target mode differs"))};reader.delimiter(b']')?;Ok(OpcRelationship{id,rel_type,target,target_mode})})?;reader.delimiter(b']')?;Ok((owner,relationships))})?;self.delimiter(b',')?;
  let relationships=OpcRelationshipOwners::adopt_admitted(owners,self.control)?;let comment=self.string()?;self.delimiter(b']')?;Ok(OpcPackage{parts,content_types:OpcContentTypes{defaults,overrides},relationships,comment})
 }
}
fn digit(byte:u8)->Result<u8,ValueError>{match byte{b'0'..=b'9'=>Ok(byte-b'0'),b'a'..=b'f'=>Ok(byte-b'a'+10),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"OPC native hexadecimal digit differs"))}}
